        void OpenBalanceScenario(BalanceScenario scenario)
        {
            if(scenario==null)return;switch(scenario.source){case "Combat":combatRequest=JsonUtility.FromJson<CombatLabRequest>(JsonUtility.ToJson(scenario.combat));playerBuild=combatRequest.player;tab=Tab.CombatLab;break;case "Drops":drop=JsonUtility.FromJson<DropLabRequest>(JsonUtility.ToJson(scenario.drop));tab=Tab.DropSimulator;break;case "Sensitivity":sensitivity=JsonUtility.FromJson<SensitivityRequest>(JsonUtility.ToJson(scenario.sensitivity));playerBuild=sensitivity.build;tab=Tab.Sensitivity;break;case "Affix":affixRequest=JsonUtility.FromJson<AffixAnalysisRequest>(JsonUtility.ToJson(scenario.affix));playerBuild=affixRequest.build;tab=Tab.AffixAnalyzer;break;case "Loot Progression":lootRequest=JsonUtility.FromJson<LootProgressionRequest>(JsonUtility.ToJson(scenario.loot));playerBuild=lootRequest.build;tab=Tab.LootProgression;break;case "Crafting":craftingRequest=JsonUtility.FromJson<CraftingSimulationRequest>(JsonUtility.ToJson(scenario.crafting));tab=Tab.CraftingSimulator;break;default:playerBuild=JsonUtility.FromJson<PlayerBuildSnapshot>(JsonUtility.ToJson(scenario.build));tab=Tab.PlayerBuildLab;break;}
        }

