            EditorGUILayout.HelpBox("Metric IDs: Combat win_rate/p50_ttk/p90_ttk/mana_starvation; Enemy dps_p50/life_p50; Drops gear_per_kill/currency_per_kill; Loot upgrades_per_100; Player uses the Player Build metric catalog.",MessageType.None);
            if(GUILayout.Button("FIND BREAKPOINT",GUILayout.Height(30)))Run("Breakpoint scan",_=>{EnsureCombat();breakResults=BreakpointFinder.Find(level=>BreakMetricAt(level),Mathf.Max(1,breakStart),Mathf.Max(breakStart,breakEnd),Mathf.Max(1,breakStep),breakThreshold,breakOperator,breakAll);foreach(var r in breakResults){r.metric=breakMetric;r.seed=combatRequest.seed;r.samples=breakSource==BreakSource.Combat?combatRequest.fightCount:breakSource==BreakSource.Drops?drop.sampleCount:1;r.fingerprint=ProductionBalanceAdapters.DataFingerprint();if(breakSource==BreakSource.Combat&&breakMetric=="win_rate"){var interval=BlackCube.BalanceWorkbench.BreakpointFinder.WilsonInterval(r.at,r.samples);r.confidenceLow=interval.low;r.confidenceHigh=interval.high;}}});
            Heading("BATCH BREAKPOINTS");breakBatchClasses=EditorGUILayout.Toggle("Across classes",breakBatchClasses);breakBatchRarities=EditorGUILayout.Toggle("Across enemy rarities",breakBatchRarities);breakBudget.initial=EditorGUILayout.IntField("Initial fights / point",breakBudget.initial);breakBudget.refinement=EditorGUILayout.IntField("Refinement fights / point",breakBudget.refinement);breakBudget.maximum=EditorGUILayout.IntField("Maximum fights / point",breakBudget.maximum);if(GUILayout.Button("RUN BATCH BREAKPOINTS"))Run("Batch breakpoints",_=>{EnsureCombat();var classes=breakBatchClasses?PlayerClassCatalog.All.Select(x=>x.Id).ToArray():new[]{playerBuild.classId};var rarities=breakBatchRarities?Enum.GetValues(typeof(EnemyAI.EnemyRarity)).Cast<EnemyAI.EnemyRarity>().ToArray():new[]{combatRequest.rarity};var cases=(from cls in classes from rarity in rarities select new BreakpointBatchCase{name=cls+" × "+rarity,classId=cls,rarity=rarity}).ToList();breakBatchResults=BreakpointFinder.FindBatch(cases,(c,l)=>BreakMetricAtCase(c,l,breakBudget.initial),breakStart,breakEnd,breakStep,breakThreshold,breakOperator,breakSource==BreakSource.Combat&&breakMetric=="win_rate"?breakBudget:null,breakSource==BreakSource.Combat&&breakMetric=="win_rate"?(c,l,n)=>BreakMetricAtCase(c,l,n):null,Progress("Batch cases"),()=>cancelled);});
            if(breakBatchResults.Count>0){Heading("BATCH TABLE — EARLIEST CROSSING FIRST");foreach(var row in breakBatchResults)EditorGUILayout.LabelField(row.scenario,$"{(row.crossingFound?"L"+row.firstCrossing:"NONE")} · {row.allCrossings} crossings · {row.before:0.###} → {row.at:0.###} vs {row.threshold:0.###} · n={row.samples} · {row.confidence}");if(breakBatchClasses&&breakBatchRarities){Heading("CLASS × RARITY HEATMAP");foreach(var cls in PlayerClassCatalog.All)EditorGUILayout.LabelField(cls.DisplayName,string.Join(" | ",Enum.GetValues(typeof(EnemyAI.EnemyRarity)).Cast<EnemyAI.EnemyRarity>().Select(r=>r+":"+(breakBatchResults.FirstOrDefault(x=>x.scenario==cls.Id+" × "+r)?.firstCrossing is int level&&level>0?level.ToString():"NONE"))));}if(GUILayout.Button("EXPORT BATCH CSV"))status=SaveAdvancedCsv("batch_breakpoints","Scenario,CrossingFound,FirstCrossing,AllCrossings,Before,At,Threshold,Samples,CILow,CIHigh,Confidence",breakBatchResults.Select(x=>$"{CsvQ(x.scenario)},{x.crossingFound},{x.firstCrossing},{x.allCrossings},{x.before:R},{x.at:R},{x.threshold:R},{x.samples},{x.confidenceLow:R},{x.confidenceHigh:R},{CsvQ(x.confidence)}"));}
            if(breakResults.Count>0){Heading("CROSSINGS");foreach(var r in breakResults)EditorGUILayout.LabelField("Level "+r.level,$"{r.before:0.####} → {r.at:0.####}; threshold {r.threshold:0.####}"+(r.samples>1&&r.metric=="win_rate"?$" · 95% CI {r.confidenceLow:P1}–{r.confidenceHigh:P1}":""));var first=breakResults[0];var metricSeries=new CurveSeries{name=breakMetric,color=Color.cyan,points=first.curve.Select(x=>new CurvePoint{x=x.level,mean=x.value}).ToList()};var thresholdSeries=new CurveSeries{name="Threshold",color=Color.yellow,points=new(){new CurvePoint{x=breakStart,mean=breakThreshold},new CurvePoint{x=breakEnd,mean=breakThreshold}}};var plot=new List<CurveSeries>{metricSeries,thresholdSeries};chart.Draw(GUILayoutUtility.GetRect(200,280,GUILayout.ExpandWidth(true)),plot,"Level",breakMetric);using(new EditorGUILayout.HorizontalScope()){if(GUILayout.Button("EXPORT CSV"))status=SaveAdvancedCsv("breakpoints","Level,Metric,Before,At,After,Threshold,Samples,Seed,CI_Low,CI_High,Fingerprint",breakResults.Select(x=>$"{x.level},{x.metric},{x.before:R},{x.at:R},{x.after:R},{x.threshold:R},{x.samples},{x.seed},{x.confidenceLow:R},{x.confidenceHigh:R},{x.fingerprint}"));if(GUILayout.Button("EXPORT PNG"))status=chart.ExportPng(plot,"breakpoints");}}
        }

        double BreakMetricAt(int level)
        {
            switch(breakSource)
            {
                case BreakSource.Combat:{var request=JsonUtility.FromJson<CombatLabRequest>(JsonUtility.ToJson(combatRequest));request.enemyLevel=level;var r=CombatLabAdapters.Batch(request);return breakMetric switch{"p50_ttk"=>r.duration.p50,"p90_ttk"=>r.duration.p90,"mana_starvation"=>r.manaStarvation.mean,_=>r.winRate};}
                case BreakSource.EnemyGear:{var r=ProductionBalanceAdapters.RunEnemies(new EnemyLabRequest{level=level,sampleCount=64,seed=combatRequest.seed,archetypeId=combatRequest.enemyArchetypeId,rarity=combatRequest.rarity});return breakMetric=="life_p50"?r.life.p50:r.dps.p50;}
                case BreakSource.Drops:{var request=JsonUtility.FromJson<DropLabRequest>(JsonUtility.ToJson(drop));request.level=level;var r=ProductionBalanceAdapters.RunDrops(request);return breakMetric=="gear_per_kill"?r.averageGearItems:r.averageCurrencyRolls;}
                case BreakSource.LootProgression:{var request=JsonUtility.FromJson<LootProgressionRequest>(JsonUtility.ToJson(lootRequest));request.combatLevel=level;request.kills=Mathf.Min(1000,request.kills);var r=LootProgressionAnalyzer.Run(request);return r.upgrades.Count*100.0/Math.Max(1,r.kills);}
                default:{var b=playerBuild.Clone();b.playerLevel=level;return OptimizationMetricCatalog.Get(breakMetric).Value(PlayerBuildEvaluator.Evaluate(b));}
            }
        }
        double BreakMetricAtCase(BreakpointBatchCase scenario,int level,int fights)
        {
            var oldBuild=playerBuild;var oldCombat=combatRequest;
            try
            {
                playerBuild=oldBuild.Clone();playerBuild.classId=scenario.classId;
                combatRequest=JsonUtility.FromJson<CombatLabRequest>(JsonUtility.ToJson(oldCombat));combatRequest.player=playerBuild;combatRequest.rarity=scenario.rarity;combatRequest.fightCount=Math.Max(1,fights);
                return BreakMetricAt(level);
            }
            finally{playerBuild=oldBuild;combatRequest=oldCombat;}
        }

