            using(new EditorGUILayout.HorizontalScope()){if(GUILayout.Button("SIMULATE UPGRADES",GUILayout.Height(30)))Run("Loot progression",_=>{lootRequest.build=playerBuild.Clone();lootRequest.objective=JsonUtility.FromJson<OptimizationObjective>(JsonUtility.ToJson(objective));lootResult=LootProgressionAnalyzer.Run(lootRequest,Progress("Kills"),()=>cancelled);});if(GUILayout.Button("COMPARE RARITIES"))Run("Loot source comparison",_=>{lootComparison.Clear();foreach(EnemyAI.EnemyRarity rarity in Enum.GetValues(typeof(EnemyAI.EnemyRarity))){if(cancelled)break;var request=JsonUtility.FromJson<LootProgressionRequest>(JsonUtility.ToJson(lootRequest));request.build=playerBuild.Clone();request.objective=objective;request.rarity=rarity;request.kills=lootComparisonKills;var compared=LootProgressionAnalyzer.Run(request,Progress(rarity.ToString()),()=>cancelled);compared.metadata.scenario=rarity.ToString();lootComparison.Add(compared);}});}
