            Heading("INDEPENDENT FIRST-UPGRADE DISTRIBUTION");using(new EditorGUILayout.HorizontalScope()){foreach(int preset in new[]{100,1000,10000})if(GUILayout.Button(preset.ToString("N0")))firstUpgradeTrials=preset;}firstUpgradeTrials=EditorGUILayout.IntField("Trials (custom)",firstUpgradeTrials);firstUpgradeMaxKills=EditorGUILayout.IntField("Maximum kills / trial",firstUpgradeMaxKills);firstUpgradeCustomThreshold=EditorGUILayout.IntField("Custom probability threshold",firstUpgradeCustomThreshold);if(GUILayout.Button("RUN FIRST-UPGRADE TRIALS"))Run("First-upgrade trials",_=>{lootRequest.build=playerBuild.Clone();lootRequest.objective=JsonUtility.FromJson<OptimizationObjective>(JsonUtility.ToJson(objective));firstUpgradeResult=LootProgressionAnalyzer.RunFirstUpgradeTrials(lootRequest,firstUpgradeTrials,firstUpgradeMaxKills,new[]{firstUpgradeCustomThreshold},Progress("Independent trials"),()=>cancelled);});
