            if(intervalResult!=null){EditorGUILayout.LabelField("Completed trials",intervalResult.trials.ToString());EditorGUILayout.LabelField("Reached upgrade #1 / #2 / #3",$"{intervalResult.firstReached} / {intervalResult.secondReached} / {intervalResult.thirdReached}");Summary("First interval",intervalResult.first);Summary("Second interval",intervalResult.second);Summary("Third interval",intervalResult.third);Summary("Later intervals",intervalResult.later);if(GUILayout.Button("EXPORT INTERVAL JSON"))status=WorkbenchExports.SaveJson("progressive_upgrade_intervals",intervalResult);}
