            if(lootComparison.Count>0){Heading("SOURCE COMPARISON");foreach(var r in lootComparison)EditorGUILayout.LabelField(r.metadata.scenario,$"{r.upgrades.Count} upgrades / {r.kills} kills");}
            if(lootWorldSweep.Count>0){Heading("WORLD SWEEP RESULTS");foreach(var row in lootWorldSweep)EditorGUILayout.LabelField("Level "+row.level,$"Gear {row.gearPerKill:0.##}/kill · Currency {row.currencyPerKill:0.##}/kill · Upgrade {row.upgradeChancePerKill:P1}/kill · Kills/upgrade {row.expectedKillsPerUpgrade:0.#} · First median {row.firstUpgradeMedian:0.#} · Boss {row.bossUpgradeContribution:P0}");if(GUILayout.Button("EXPORT WORLD SWEEP CSV"))status=SaveAdvancedCsv("world_loot_sweep","Level,Kills,GearPerKill,CurrencyPerKill,UpgradeChance,ExpectedKillsPerUpgrade,FirstUpgradeMedian,AverageUpgradeMagnitude,BossContribution,RareLegendaryContribution",lootWorldSweep.Select(x=>$"{x.level},{x.kills},{x.gearPerKill:R},{x.currencyPerKill:R},{x.upgradeChancePerKill:R},{x.expectedKillsPerUpgrade:R},{x.firstUpgradeMedian:R},{x.averageUpgradeMagnitude:R},{x.bossUpgradeContribution:R},{x.rareLegendaryContribution:R}"));}
