            Heading("BOUNDED POLICY SEARCH");craftSearch.beamWidth=EditorGUILayout.IntSlider("Beam width",craftSearch.beamWidth,1,30);craftSearch.maxCraftActions=EditorGUILayout.IntSlider("Search depth",craftSearch.maxCraftActions,1,20);craftSearch.candidateOutcomesPerAction=EditorGUILayout.IntSlider("Random outcomes / candidate",craftSearch.candidateOutcomesPerAction,1,100);craftSearch.maximumStates=EditorGUILayout.IntSlider("Maximum states",craftSearch.maximumStates,1,500);craftSearch.seed=EditorGUILayout.LongField("Search seed",craftSearch.seed);if(GUILayout.Button("SEARCH BEST DISCOVERED POLICY"))Run("Craft policy search",_=>{craftSearch.simulation=JsonUtility.FromJson<CraftingSimulationRequest>(JsonUtility.ToJson(craftingRequest));craftSearch.allowedActions=craftingRequest.policy.Select(x=>JsonUtility.FromJson<CraftPolicyStep>(JsonUtility.ToJson(x))).ToList();craftSearchResult=CraftingPolicySearcher.Search(craftSearch,Progress("Search states"),()=>cancelled);});
            if(craftSearchResult!=null){EditorGUILayout.HelpBox(craftSearchResult.label+$" · {craftSearchResult.evaluatedStates}/{craftSearchResult.stateCap} states",MessageType.Info);foreach(var discovered in craftSearchResult.topPolicies.Take(10)){using(new EditorGUILayout.HorizontalScope()){EditorGUILayout.LabelField(string.Join(" → ",discovered.steps.Select(x=>x.operation==CraftOperation.Ordinary?x.action.ToString():x.operation.ToString())),$"Estimated {discovered.estimatedSuccessRate:P1} · P50 cost {discovered.medianCost:0.#} · P90 {discovered.p90Cost:0.#}");if(GUILayout.Button("VALIDATE POLICY",GUILayout.Width(130)))Run("Policy validation",_=>craftingResult=CraftingPolicySearcher.Validate(craftSearch,discovered,craftValidationTrials,Progress("Independent crafts"),()=>cancelled));}}craftValidationTrials=EditorGUILayout.IntPopup("Validation trials",craftValidationTrials,new[]{"1,000","10,000"},new[]{1000,10000});}
            if(GUILayout.Button("RUN CRAFTING SIMULATOR",GUILayout.Height(30)))Run("Crafting trials",_=>craftingResult=CraftingSimulator.Run(craftingRequest,Progress("Crafts"),()=>cancelled));if(craftingResult==null)return;if(craftingResult.Stale)EditorGUILayout.HelpBox("STALE — PRODUCTION DATA CHANGED",MessageType.Warning);EditorGUILayout.LabelField("Success rate",craftingResult.trials==0?"n/a":$"{craftingResult.successes} / {craftingResult.trials} ({craftingResult.successes/(double)craftingResult.trials:P2})");if(craftingResult.successes==0&&craftingResult.trials>0)EditorGUILayout.LabelField("95% success upper bound",BreakpointFinder.WilsonInterval(0,craftingResult.trials).high.ToString("P2"));EditorGUILayout.LabelField("Potential / resource / progression failures",$"{craftingResult.potentialFailures} / {craftingResult.budgetFailures} / {craftingResult.progressionFailures}");Summary("Action count",craftingResult.actions);Summary("Final target matches",craftingResult.finalMatches);Summary("Potential at failed stop",craftingResult.failurePotential);foreach(var c in craftingResult.costs)EditorGUILayout.LabelField(c.currency.ToString(),$"Mean {c.mean:0.##} · P50 {c.p50:0.##} · P90 {c.p90:0.##} · P95 {c.p95:0.##} · P99 {c.p99:0.##}");foreach(var c in craftingResult.resourceCosts)EditorGUILayout.LabelField(c.resourceId,c.amount+" consumed");if(craftingResult.bestFailure?.finalItem!=null){if(GUILayout.Button("INSPECT BEST FAILURE"))EditorUtility.DisplayDialog("Best partial item",craftingResult.bestFailure.finalItem.Description,"Close");if(GUILayout.Button("REPLAY FAILURE"))status=WorkbenchExports.SaveJson("craft_best_failure_replay",craftingResult.bestFailure);}if(GUILayout.Button("SEND TARGET TO POLICY SEARCH")){craftSearch.simulation=JsonUtility.FromJson<CraftingSimulationRequest>(JsonUtility.ToJson(craftingRequest));status="Target copied to bounded policy search.";}if(craftingResult.replay!=null){Heading("REPLAY ATTEMPT");foreach(var step in craftingResult.replay.trace)EditorGUILayout.LabelField($"{step.number}. {step.operation} {step.action}",$"Potential {step.potentialBefore} → {step.potentialAfter} {step.failureReason}");if(GUILayout.Button("EXPORT TRACE JSON"))status=WorkbenchExports.SaveJson("craft_trace",craftingResult.replay);}
            if(GUILayout.Button("EXPORT CRAFTING CSV"))status=SaveAdvancedCsv("crafting_result","Trials,Successes,PotentialFailures,BudgetFailures,MedianActions,P90Actions",new[]{$"{craftingResult.trials},{craftingResult.successes},{craftingResult.potentialFailures},{craftingResult.budgetFailures},{craftingResult.actions.p50:R},{craftingResult.actions.p90:R}"});
        }

        static string CsvQ(string value)=>"\""+(value??"").Replace("\"","\"\"")+"\"";
        static string SaveAdvancedCsv(string name,string header,IEnumerable<string> rows){Directory.CreateDirectory(WorkbenchExports.Root);string path=Path.Combine(WorkbenchExports.Root,name+"_"+DateTime.UtcNow.ToString("yyyyMMdd_HHmmss")+".csv");File.WriteAllLines(path,new[]{header}.Concat(rows));AssetDatabase.Refresh();return path;}
    }
}
